head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > E > onclick]<br/>accordion 컴포넌트의 패널 타이틀 영역을 클릭할 때 발생합니다.",
    "validation" : [
        "accordion 컴포넌트의 패널 타이틀 영역을 클릭할 때 발생합니다.",
        "panel 클릭된 패널이 객체로 전달됩니다.",
        "open 클릭 후 패널의 열림 상태가 전달됩니다.",
        "클릭에 의해 패널이 열리는 경우 true 값, 닫히는 경우 false 값을 갖습니다.",
        "disabledPanels=true 인 패널을 클릭하면 onclick 이벤트가 발생하지 않습니다.",
        "enterKeyPanelToggle=true 일때 포커스가 있는 패널에서 Enter 키를 누르면 onclick 이벤트가 발생합니다.",
        "onpanelload, onpanelunload 이벤트는 슬라이드 애니메이션이 완료된 후 콜백에서 발생하므로, onclick 이벤트보다 비동기적으로 나중에 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        enterKeyPanelToggle : con_enterKeyPanelToggle.getText(),
        collapsible : "true",
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick", "onpanelload", "onpanelunload"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* panels1, panels2 : 일반 패널 / panels3 : disabledPanels=true 패널 (클릭해도 onclick 미발생)"', '', 'label1');
    $c.gcm.createLabel('label="* panelTitle 클릭 시 onclick(panel, open) → 패널 열림 시 open=true, 닫힘 시 open=false 전달"', '', 'label2');
    $c.gcm.createLabel('label="* enterKeyPanelToggle=true 일 때 panelTitle 포커스 후 Enter 키 입력으로도 onclick 발생"', '', 'label3');
    $c.gcm.createLabel('label="* 이벤트 발생 순서 : onclick → (애니메이션 완료 후) onpanelload / onpanelunload 비동기 발생"', '', 'label4');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="" userID="userPanel1">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="" userID="userPanel2">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="" userID="userPanel3" disabledPanels="true">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3 (disabledPanels=true)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// onclick 핸들러 — 가이드 @param : <Object> panel, <Boolean> open
scwin.target1_onclick = function (panel, open) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== onclick 이벤트 발생 =====");
    wf_body_bottom.getObj("scwin").setReturnValue("panel.id : " + (panel ? panel.id : panel));
    wf_body_bottom.getObj("scwin").setReturnValue("open : " + open);
};



// onpanelload 핸들러 — 이벤트 순서 검증용 (onclick 이후 비동기 발생)
scwin.target1_onpanelload = function (panelID, userID) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onpanelload 이벤트 발생]");
};



// onpanelunload 핸들러 — 이벤트 순서 검증용 (onclick 이후 비동기 발생)
scwin.target1_onpanelunload = function (panelID, userID) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onpanelunload 이벤트 발생]");
};



// par_panelId 의 panelTitle 영역에 포커스 (accessibility=true 면 a태그, false 면 div 에 tabindex 부여 후 포커스)
scwin.btn_focusPanelTitle_onclick = function (e) {
    let panelId = par_panelId.getValue();
    let titleEl = target1.render.querySelector("[id$='_panel_" + panelId + "_title']");
    if (titleEl) {
        let focusTarget = titleEl.querySelector("a") || titleEl;
        if (!focusTarget.hasAttribute("tabindex")) {
            focusTarget.setAttribute("tabindex", "0");
        }
        focusTarget.focus();
        wf_body_bottom.getObj("scwin").setReturnValue("===== '" + panelId + "' panelTitle 포커스 =====");
    }
};



// 현재 열린 패널 정보 출력 (getOpenPanelListInfo)
scwin.btn_getOpenPanel_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelListInfo() 결과 =====");
    let openList = target1.getOpenPanelListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 수 : " + (openList ? openList.length : 0));
    if (openList && openList.length > 0) {
        for (let i = 0; i < openList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("열린 패널[" + i + "] id : " + openList[i].id);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 없음 (모두 닫힘)");
    }
};
